insert into palestras (id, titulo, palestrante, sala, trilha, tipo, inicio, fim, vagas, inscritos, remanejada_de, descricao) values
  ('00000000-0000-0000-0000-000000000001', 'O Deploy de Sexta: Ao Vivo', 'Marina Prod', 'Auditório Legacy', 'carreira', 'keynote', '2026-10-24T09:00:00-03', '2026-10-24T10:00:00-03', 300, 187, null, 'A keynote de abertura da MergeConf 2026. Marina faz um deploy em produção no palco, numa sexta-feira, sem rede de segurança. O que pode dar errado é o roteiro.'),
  ('00000000-0000-0000-0000-000000000002', 'useEffect: Uma História de Terror', 'Carlos Render', 'Sala Stack Overflow', 'frontend', 'talk', '2026-10-24T10:30:00-03', '2026-10-24T11:15:00-03', 80, 64, '2026-10-24T14:00:00-03', 'Cinco dependências, três race conditions e um cleanup que nunca roda. Baseado em fatos reais do repositório da sua empresa.'),
  ('00000000-0000-0000-0000-000000000003', 'Microserviços: Como Transformar 1 Problema em 47', 'Rafa Broker', 'Auditório Legacy', 'backend', 'talk', '2026-10-24T10:30:00-03', '2026-10-24T11:15:00-03', 300, 143, null, 'Um monolito virou 47 serviços e agora ninguém sabe onde mora o bug. Um guia sincero de quando (não) distribuir.'),
  ('00000000-0000-0000-0000-000000000004', 'Escalando o Monólito com Fé', 'Dona Estela Singleton', 'Sala Rubber Duck', 'backend', 'talk', '2026-10-24T11:30:00-03', '2026-10-24T12:15:00-03', 60, 41, null, 'O monolito aguenta. Sempre aguentou. Técnicas de cache, filas e oração para adiar a grande reescrita por mais um ano fiscal.'),
  ('00000000-0000-0000-0000-000000000005', 'CSS: A Arte de Centralizar uma Div em 2026', 'Bea Flexbox', 'Sala Stack Overflow', 'frontend', 'talk', '2026-10-24T11:30:00-03', '2026-10-24T12:15:00-03', 80, 77, null, 'Grid, flex, anchor positioning e as 14 formas de centralizar — incluindo a que funciona no navegador do seu cliente.'),
  ('00000000-0000-0000-0000-000000000006', 'Prompt Engineering: Falando Bonito com a Máquina', 'Ju Tokens', 'Auditório Legacy', 'ia', 'talk', '2026-10-24T13:30:00-03', '2026-10-24T14:15:00-03', 300, 205, null, 'Contexto, objetivo, restrições e critérios de aceite: por que o prompt do seu colega funciona e o seu não.'),
  ('00000000-0000-0000-0000-000000000007', 'RAG: Seu Chatbot Decorou a Wiki Errada', 'Otto Embedding', 'Sala Rubber Duck', 'ia', 'talk', '2026-10-24T13:30:00-03', '2026-10-24T14:15:00-03', 60, 58, null, 'Retrieval que recupera a página errada, chunks cortados no meio da frase e a arte de culpar o modelo pelo seu pipeline.'),
  ('00000000-0000-0000-0000-000000000008', 'Do Estágio ao Burnout em 18 Meses', 'Léo Sprint', 'Sala Stack Overflow', 'carreira', 'talk', '2026-10-24T14:30:00-03', '2026-10-24T15:15:00-03', 80, 52, null, 'Uma retrospectiva honesta sobre dizer sim para tudo. Inclui o gráfico de commits às 2h da manhã e como sair dessa curva.'),
  ('00000000-0000-0000-0000-000000000009', 'Testes: Escrevendo o que Você Jurou que Ia Escrever', 'Vera Coverage', 'Sala Rubber Duck', 'backend', 'workshop', '2026-10-24T14:30:00-03', '2026-10-24T16:30:00-03', 40, 33, null, 'Workshop mão na massa: pegamos um serviço real sem nenhum teste e saímos com uma suíte que o time tem orgulho de rodar.'),
  ('00000000-0000-0000-0000-000000000010', 'Git Rebase Sem Chorar (Quase)', 'Chico Conflitos', 'Sala Stack Overflow', 'carreira', 'workshop', '2026-10-24T15:30:00-03', '2026-10-24T17:30:00-03', 40, 39, null, 'Workshop prático de reescrita de histórico: interactive rebase, fixup, autosquash e o momento exato de desistir e fazer merge.'),
  ('00000000-0000-0000-0000-000000000011', 'Kubernetes: O Cluster que Ninguém Sabe Quem Criou', 'Helena Helm', 'Auditório Legacy', 'backend', 'talk', '2026-10-24T16:00:00-03', '2026-10-24T16:45:00-03', 30, 29, null, 'Arqueologia de infraestrutura: entendendo um cluster herdado onde todo manifesto tem um "não mexer" no comentário. Sala pequena, corre que está acabando.'),
  ('00000000-0000-0000-0000-000000000012', 'Acessibilidade: O Requisito que Virou Lenda', 'Alice Aria', 'Sala Rubber Duck', 'frontend', 'talk', '2026-10-24T17:00:00-03', '2026-10-24T17:45:00-03', 60, 21, '2026-10-24T09:00:00-03', 'Todo mundo diz que é prioridade, ninguém coloca na sprint. Como sair do discurso e fazer um formulário que uma pessoa cega consegue enviar.');
